__require("routes/auth")(router);
__require("routes/scans")(router);
__require("routes/officers")(router);
__require("routes/blacklist")(router);
__require("routes/registry")(router);
__require("routes/stats")(router);
__require("routes/public-check")(router);

const publicDir = path.join(__dirname, "public");
const serveFile = serveStatic(publicDir);

// Standalone per-Exhibit pages generated from index.html (see build_exhibits.py),
// linked from each Exhibit's "Open as page" link on the public site. Purely
// additive — index.html's own single-page tab-switching demo is untouched.
const exhibitsDir = path.join(__dirname, "exhibits");
const serveExhibit = serveStatic(exhibitsDir);

// The custom domain veriscanx.in is meant to show the public marketing/demo
// site (root index.html), not the officer panel — the officer panel stays
// reachable at its own Render URL (and at /login.html on any host, for
// anyone who bookmarked it). Only the bare "/" on the public-site hostnames
// is special-cased; every other path (API routes, panel assets) behaves the
// same regardless of which hostname the request came in on.
const PUBLIC_SITE_HOSTS = new Set(["veriscanx.in", "www.veriscanx.in"]);
const PUBLIC_SITE_INDEX = path.join(__dirname, "index.html");

const PORT = process.env.PORT || 4000;

const server = http.createServer(async (req, res) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
  res.setHeader("Access-Control-Allow-Methods", "GET,POST,PATCH,DELETE,OPTIONS");
  if (req.method === "OPTIONS") { res.writeHead(204); res.end(); return; }

  const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);
  const pathname = decodeURIComponent(url.pathname);
  const hostHeader = (req.headers.host || "").split(":")[0].toLowerCase();

  if (pathname === "/" && PUBLIC_SITE_HOSTS.has(hostHeader) && fs.existsSync(PUBLIC_SITE_INDEX)) {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    fs.createReadStream(PUBLIC_SITE_INDEX).pipe(res);
    return;
  }

  if (pathname.startsWith("/exhibits/") && fs.existsSync(exhibitsDir)) {
    const rel = pathname.slice("/exhibits".length);
    if (serveExhibit(req, res, rel)) return;
  }

  if (pathname.startsWith("/api/")) {
    const match = router.match(req.method, pathname);
    if (!match) return sendJSON(res, 404, { error: "Not found" });
    req.query = url.searchParams;
    try {
      await match.handler(req, res, match.params);
    } catch (err) {
      if (err instanceof HttpError) {
        sendJSON(res, err.statusCode, { error: err.message });
      } else {
        console.error(err);
        sendJSON(res, 500, { error: "Internal server error" });
      }
    }
    return;
  }

  const served = serveFile(req, res, pathname);
  if (!served) {
    res.writeHead(404, { "Content-Type": "text/plain" });
    res.end("Not found");
  }
});

server.listen(PORT, () => {
  console.log(`\n  VeriScanx panel running → http://localhost:${PORT}\n`);
});
